export const meta = {
  name: "draft_ideas_0_1_avatar_profile_asset_pack",
  description: "Export Kit's active avatar as a profile-ready PNG asset pack (transparent/light/dark, 512/1024px) for IWSDK READMEs and posts.",
  phases: [
    { name: "produce", detail: "Fetch active avatar and render export variants" },
    { name: "verify", detail: "Check PNGs match avatar, dimensions, and packaging" }
  ]
};

const PRODUCE_SCHEMA = {
  type: "object",
  required: ["summary", "finalArtifacts", "spaceSlug", "variantPaths"],
  properties: {
    summary: { type: "string" },
    spaceSlug: { type: ["string", "null"] },
    variantPaths: {
      type: "array",
      items: { type: "string" }
    },
    finalArtifacts: {
      type: "array",
      items: {
        type: "object",
        required: ["type", "title", "path"],
        properties: {
          type: { type: "string" },
          title: { type: "string" },
          path: { type: "string" },
          primary: { type: "boolean" }
        },
        additionalProperties: false
      }
    }
  },
  additionalProperties: false
};

const VERIFY_SCHEMA = {
  type: "object",
  required: ["approved", "retryable", "summary", "feedback", "blockers"],
  properties: {
    approved: { type: "boolean" },
    retryable: { type: "boolean" },
    summary: { type: "string" },
    feedback: { type: "string" },
    blockers: { type: "array", items: { type: "string" } }
  },
  additionalProperties: false
};

const MAX_ATTEMPTS = 3;
const ONE_HOUR_MS = 60 * 60 * 1000;
const THIRTY_MINUTES_MS = 30 * 60 * 1000;

function producePrompt(feedback, previousOutput) {
  return `Create the Kit Avatar Profile Asset Pack.

Idea promise:
Export my current Kit avatar as a clean dev-profile image set — transparent PNG, plus light and dark backgrounds, at 512px and 1024px, ready to drop into IWSDK READMEs, GitHub releases, and Threads posts. Produce 6 PNGs total, zipped with usage notes. My active Hatch avatar is unchanged.

You must:

1. Fetch the current active Kit avatar.
   - Call the avatar tool with operation:"get" to retrieve the active avatar image.
   - This is real user data — use the actual returned avatar. Never synthesize, generate a new character, or substitute a placeholder. If the avatar tool fails or returns no image, stop and return a precise blocker.
   - Save the source avatar in the workflow working directory (exec commands start there). Do not put source inputs in workspace/your_files/.

2. Render 6 profile-ready exports, preserving character identity exactly:
   - kit-avatar-transparent-512.png  — 512×512, transparent background, square crop, centered head/upper torso
   - kit-avatar-transparent-1024.png — 1024×1024, transparent background
   - kit-avatar-light-512.png       — 512×512, light neutral background
   - kit-avatar-light-1024.png      — 1024×1024, light neutral background
   - kit-avatar-dark-512.png        — 512×512, dark neutral background
   - kit-avatar-dark-1024.png       — 1024×1024, dark neutral background
   All crops are square, centered, readable at small sizes, character look matches the active avatar exactly.

3. Write final deliverables to workspace/your_files/kit-avatar-pack/:
   - the 6 PNGs above
   - kit-avatar-pack.zip containing the 6 PNGs plus a brief README.txt with usage note ("Kit avatar profile exports — transparent / light / dark, 512px / 1024px")
   - README.txt also written standalone in that folder for inspection

Put every helper script, source download, intermediate render, and working file in the shared workflow working directory. Exec commands start there by default. The final workspace/your_files/kit-avatar-pack/ directory must contain only finished user-facing files (the 6 PNGs, README.txt, kit-avatar-pack.zip). No source code, build logs, or verifier files in workspace/your_files/.

4. Verify locally before returning: all 6 PNGs exist, dimensions are correct (512 or 1024 square), backgrounds match (transparent / light / dark), and the character matches the active avatar fetched in step 1.

${feedback ? `Verifier feedback from previous attempt:
${feedback}

Repair the issue directly while preserving the idea promise. Reuse the same output paths in workspace/your_files/kit-avatar-pack/.` : ""}

${previousOutput?.spaceSlug ? `Note: previous attempt spaceSlug: ${previousOutput.spaceSlug}` : ""}

Return JSON matching the schema with:
- summary: short user-facing description of what was produced
- spaceSlug: null (no web artifact)
- variantPaths: array of the 6 PNG workspace paths
- finalArtifacts: include at minimum the zip at workspace/your_files/kit-avatar-pack/kit-avatar-pack.zip with primary:true, type:"file", title:"Kit Avatar Profile Asset Pack"
You may also list the 6 individual PNGs as secondary artifacts.

Do not create a web artifact, PDF, DOCX, or markdown deliverable for this — the deliverable is the PNG zip pack.`;
}

function verifyPrompt(outputs, attempt) {
  return `Verify the Kit Avatar Profile Asset Pack.

Attempt: ${attempt}
Outputs: ${JSON.stringify(outputs, null, 2)}

Check:
1. Real avatar source was used — outputs were derived from a generate_avatar get call, character matches Felix's known Kit avatar (compact plush robot, smooth matte steel-blue/white shell, friendly glowing cyan eyes). Reject synthesized / placeholder / wrong-character avatars.
2. All 6 required PNGs exist in workspace/your_files/kit-avatar-pack/: transparent/light/dark × 512/1024, correct dimensions, square, centered.
3. Backgrounds are correct: transparent files actually have alpha, light files have a clean light neutral background, dark files have a clean dark neutral background.
4. Character identity is preserved across all variants and matches the active avatar.
5. kit-avatar-pack.zip exists at workspace/your_files/kit-avatar-pack/kit-avatar-pack.zip and contains the 6 PNGs plus a README.
6. No avatar change occurred — this is an export pack only.
7. Final artifacts are finished user-facing files under workspace/your_files/, not source/build/verifier files.

Return JSON with approved, retryable, summary, feedback, blockers.
Set approved=true only if all checks pass.
Set retryable=true only when the producer can fix the issue with clear feedback (wrong dimensions, bad crop, missing file, etc.).
Set retryable=false for non-repairable data issues: fabricated avatar (not from generate_avatar get), wrong character, or inability to fetch the real active avatar — those are blockers, not repair feedback.`;
}

const inputs = args ?? {};

let feedback = "";
let previousOutput = null;
let verified = null;
let produced = null;

for (let attempt = 1; attempt <= MAX_ATTEMPTS; attempt++) {
  produced = await agent(producePrompt(feedback, previousOutput), {
    key: `produce-${attempt}`,
    label: `Produce avatar asset pack${attempt > 1 ? ` (repair ${attempt})` : ""}`,
    phase: "produce",
    timeoutMs: ONE_HOUR_MS,
    schema: PRODUCE_SCHEMA
  });

  if (!produced) {
    throw new Error(`Produce step failed on attempt ${attempt} — null result`);
  }

  verified = await agent(verifyPrompt([produced], attempt), {
    key: `verify-${attempt}`,
    label: "Verify avatar pack",
    phase: "verify",
    timeoutMs: THIRTY_MINUTES_MS,
    schema: VERIFY_SCHEMA
  });

  if (verified.approved) {
    break;
  }
  if (!verified.retryable || attempt === MAX_ATTEMPTS) {
    break;
  }
  feedback = verified.feedback || verified.summary;
  previousOutput = produced;
}

if (!verified || !verified.approved) {
  const message = verified && verified.blockers.length > 0
    ? verified.blockers.join("; ")
    : (verified ? verified.summary : "Verification did not produce a result.");
  return {
    __hatchWorkflowControl: "blocked",
    result: {
      blocked_reason: "verification_blocked",
      message
    }
  };
}

const finalArtifacts = Array.isArray(produced.finalArtifacts) ? produced.finalArtifacts : [];
const primary = finalArtifacts.find(a => a.primary) || finalArtifacts[0];

return {
  status: "completed",
  summary: produced.summary,
  handback: primary
    ? { message: produced.summary, artifacts: [primary] }
    : { message: produced.summary }
};

