  name: "draft_ideas_2_2_vr_ship_threads_draft",
  description: "Draft an approval-ready Threads ship post for the latest IWSDK VR build, with screenshot, genre, and Pages link.",
  phases: [
    { name: "plan", detail: "Locate latest shipped VR build and verify Threads access" },
    { name: "produce", detail: "Compose Threads draft with real build metadata and screenshot" },
    { name: "verify", detail: "Confirm draft matches ship-post promise and uses real data" }
