    threadsAvailable: { type: "boolean" },
    missingInputs: { type: "array", items: { type: "string" } },
    sourceEvidence: { type: "string" }
  },
  additionalProperties: true
};

const PRODUCE_SCHEMA = {
  type: "object",
  required: ["buildName", "genre", "pagesUrl", "postText", "screenshotPath", "threadsAccountOk", "sourceEvidence", "summary"],
  properties: {
    buildName: { type: "string" },
    genre: { type: "string" },
    pagesUrl: { type: "string" },
    postText: { type: "string" },
