  },
  additionalProperties: false
};

const MAX_ATTEMPTS = 3;
const THIRTY_MINUTES_MS = 30 * 60 * 1000;
const ONE_HOUR_MS = 60 * 60 * 1000;

function planPrompt(inputs) {
  return `Plan a Threads ship draft for Felix's IWSDK VR arcade.

Idea promise:
After each AM/PM VR build deploys to GitHub Pages, draft an approval-ready Threads post with: build name + genre, live URL, one-line hook, and the headless build screenshot. Draft only — no auto-post. User approves before posting.

Activation inputs / prerequisite answers:
${JSON.stringify(inputs, null, 2)}

Your task:
1. Locate the latest completed VR build. Check in order:
   - ~/workspace/iwsdk-daily-builds/current-build-status-pm.json
   - ~/workspace/iwsdk-daily-builds/current-build-status.json
   Prefer a build with status:"complete".
   Read BUILD_LOG.md at ~/workspace/iwsdk-daily-builds/BUILD_LOG.md for genre/LOC confirmation.
   If no completed build is found, fall back to the most recent known ship: Neon Mind VR #129 — Mastermind Code-Breaking Logic, Pages https://ellyz2426.github.io/neon-mind/, game_dir /home/hatch/workspace/neon-mind

2. Extract: buildName, genre, pagesUrl, gameDir, LOC if available.

3. Find a build screenshot in the gameDir root. Common names: screenshot-*.png. Pick the most recent / most representative (menu or gameplay). Return its absolute workspace path. If no screenshot exists, note it in missingInputs — do not invent one.

4. Verify Threads posting capability:
   - Check if the Threads skill / connector is available in this environment.
   - Do NOT post anything. Only verify access / account presence.
   - Set threadsAvailable true if the connector/skill can be invoked, false otherwise with a precise reason.
   - Previous memory notes: Threads account was connected 2026-04-27, CLI auth expired 2026-05-05, daily report retired 2026-05-20. Verify live, do not assume.

5. Parse activation inputs for preferences:
   - ideaUserInput may contain: posting account handle override, includeLoc true/false, genre tags preference.
   - Default: includeLoc = true, include tags #WebXR #IWSDK.
   - If Threads account handle is missing and the connector requires it, list "threads_account_handle" in missingInputs.

Return JSON matching PLAN_SCHEMA.
- missingInputs must be [] if you found a build + screenshot and Threads is reachable, otherwise list exactly what is blocking (e.g. "threads_connection", "build_screenshot", "threads_account_handle").
- sourceEvidence: short string citing where build metadata came from, e.g. "current-build-status-pm.json, BUILD_LOG.md #129, screenshot /home/hatch/workspace/neon-mind/screenshot-r8-menu.png".
- threadsAvailable is a boolean — do not fake it, verify live.`;
}

function producePrompt(plan, inputs, feedback, previousOutput) {
  return `Compose an approval-ready Threads ship draft for Felix's latest IWSDK VR build.

Build plan context:
${JSON.stringify(plan, null, 2)}

Activation inputs:
${JSON.stringify(inputs, null, 2)}

${feedback ? `Verifier feedback from previous attempt:
${feedback}

Repair the issue directly while preserving the idea promise.` : ""}

Requirements — this is real user data, no placeholders:
1. Use the real build metadata from the plan step. Do NOT invent build names, genres, URLs, or LOC.
   - Confirmed recent ship for verification: Neon Mind VR #129 — Mastermind Code-Breaking Logic, https://ellyz2426.github.io/neon-mind/
   - If plan found a newer completed build, use that instead, with evidence.

2. Acquire real data with evidence:
   - Read ~/workspace/iwsdk-daily-builds/current-build-status-pm.json and/or current-build-status.json
   - Read BUILD_LOG.md for genre / LOC cross-check
   - Locate the screenshot file in the gameDir (e.g. /home/hatch/workspace/neon-mind/screenshot-r8-menu.png) — confirm it exists on disk, return its absolute path.
   - Never substitute a fake, sample, generated, or stock image. If the screenshot is missing, return a precise blocker instead of inventing one.

3. Verify Threads access live:
   - Confirm the Threads skill / connector is present and can draft posts.
   - Do NOT post, do NOT auto-publish. Draft only.
   - Set threadsAccountOk true only if posting is possible with user approval. If not, explain why in the output — do not fake success.

4. Compose the Threads draft text:
   - Format: "<Game> — <genre> VR, live now: <url> #WebXR #IWSDK"
   - Add a concise one-line hook describing the game (max ~140 chars total post recommended).
   - Include LOC only if includeLoc is true (default yes).
   - Keep Felix's voice: direct, technical, no hype filler.
   - Example: "Neon Mind VR — Mastermind Code-Breaking Logic VR, live now: https://ellyz2426.github.io/neon-mind/ #WebXR #IWSDK"
   - Return the full postText string.

5. Respect the approval gate:
   - This workflow only drafts. Do not call any Threads publish API.
   - The handback must make clear the draft is ready for Approve / Edit / Skip.

6. Output JSON matching PRODUCE_SCHEMA:
   - buildName, genre, pagesUrl, postText, screenshotPath (absolute, verified exists), threadsAccountOk, loc, includeLoc
   - sourceEvidence: e.g. "status-pm.json build 129, BUILD_LOG.md, screenshot-r8-menu.png exists"
   - summary: short user-facing description, e.g. "Threads ship draft ready for Neon Mind VR — Mastermind, https://ellyz2426.github.io/neon-mind/, screenshot attached, awaiting approval."

Do not create a PDF, DOCX, web artifact, or any file in workspace/your_files/ — this is a chat-delivered draft. If you create helper files, keep them in the workflow working directory (exec starts there).

If Threads access is missing, if the build screenshot cannot be found, or if real build metadata cannot be acquired, do NOT synthesize. Return a JSON with threadsAccountOk=false and explain the blocker in summary — the verifier will treat fabricated data as a non-retryable failure.`;
}

function verifyPrompt(produced, attempt) {
  return `Verify the VR Ship Threads Draft output.

Attempt: ${attempt}
Output:
${JSON.stringify(produced, null, 2)}

Check against the idea promise:
"After each AM/PM VR build deploys to GitHub Pages, a Threads draft in chat with: build name + genre, live URL, one-line hook, and the headless screenshot from the build. You approve before posting. Privacy: drafts only, no auto-post."

Validation:
1. Real data — buildName, genre, pagesUrl match a real entry in ~/workspace/iwsdk-daily-builds/BUILD_LOG.md and current-build-status*.json. Reject fabricated builds. For the baseline verification build Neon Mind VR #129: pagesUrl must be https://ellyz2426.github.io/neon-mind/, genre "Mastermind Code-Breaking Logic" or similar Mastermind wording.
2. postText includes build name, genre/VR tag, live Pages URL, and #WebXR #IWSDK tags (or equivalent), plus a concise hook. No hype filler, matches Felix's direct tone.
3. screenshotPath is an absolute workspace path, file exists, is a PNG from the game's build folder (e.g. /home/hatch/workspace/neon-mind/screenshot-*.png), not a generated/stock placeholder.
4. threadsAccountOk reflects actual Threads skill availability — do not approve if the producer faked this. Previous history: Threads auth expired 2026-05-05 — verify live evidence, not memory alone.
5. Approval gate respected — output is draft-only, no claim of auto-posting, summary clearly states awaiting approval.
6. sourceEvidence names the specific status JSON, BUILD_LOG entry, and screenshot file used.
7. No unexpected files in workspace/your_files/ — this is chat delivery.
8. If any data is synthetic, placeholder, or unsourced, set approved=false, retryable=false, and list blockers.

Return JSON with approved, retryable, summary, feedback, blockers.
Set approved=true only if all checks pass.
Set retryable=true only when the producer can fix with feedback (e.g. missing hashtag, wrong URL format, bad hook length).
Set retryable=false for data fabrication, missing real screenshot, wrong build metadata, or Threads access falsely claimed — those are blockers.`;
}

const inputs = args ?? {};

phase("plan");
const plan = await agent(planPrompt(inputs), {
  key: "plan",
  label: "Plan Threads ship draft",
  phase: "plan",
  timeoutMs: THIRTY_MINUTES_MS,
  schema: PLAN_SCHEMA
});

if (!plan || (Array.isArray(plan.missingInputs) && plan.missingInputs.length > 0)) {
  const missing = plan?.missingInputs?.join(", ") || "planning_failed";
  return {
    __hatchWorkflowControl: "blocked",
    result: {
      blocked_reason: "missing_inputs",
      message: `Threads ship draft needs: ${missing}. Connect Threads via Account Center and confirm posting account handle. A build screenshot must exist in the game folder (e.g. screenshot-r8-menu.png).`
    }
  };
}

let feedback = "";
