const inputs = args ?? {};

phase("plan");
const plan = await agent(planPrompt(inputs), {
  key: "plan",
  label: "Plan Threads ship draft",
  phase: "plan",
  timeoutMs: THIRTY_MINUTES_MS,
  schema: PLAN_SCHEMA
});

if (!plan || (Array.isArray(plan.missingInputs) && plan.missingInputs.length > 0)) {
  const missing = plan?.missingInputs?.join(", ") || "planning_failed";
  return {
    __hatchWorkflowControl: "blocked",
    result: {
      blocked_reason: "missing_inputs",
      message: `Threads ship draft needs: ${missing}. Connect Threads via Account Center and confirm posting account handle. A build screenshot must exist in the game folder (e.g. screenshot-r8-menu.png).`
    }
  };
}

let feedback = "";
let previousOutput = null;
let verified = null;
let produced = null;

for (let attempt = 1; attempt <= MAX_ATTEMPTS; attempt++) {
  phase("produce");
  produced = await agent(producePrompt(plan, inputs, feedback, previousOutput), {
    key: `produce-${attempt}`,
    label: `Compose Threads draft${attempt > 1 ? ` (repair ${attempt})` : ""}`,
    phase: "produce",
    timeoutMs: ONE_HOUR_MS,
    schema: PRODUCE_SCHEMA
  });

  if (!produced) {
    throw new Error(`Produce step failed on attempt ${attempt} — null result`);
  }

  phase("verify");
  verified = await agent(verifyPrompt(produced, attempt), {
    key: `verify-${attempt}`,
    label: "Verify Threads draft",
    phase: "verify",
    timeoutMs: THIRTY_MINUTES_MS,
    schema: VERIFY_SCHEMA
  });

  if (verified.approved) {
    break;
  }
  if (!verified.retryable || attempt === MAX_ATTEMPTS) {
    break;
  }
  feedback = verified.feedback || verified.summary;
  previousOutput = produced;
}

if (!verified || !verified.approved) {
  const message = verified && verified.blockers.length > 0
    ? verified.blockers.join("; ")
    : (verified ? verified.summary : "Verification did not produce a result.");
  return {
    __hatchWorkflowControl: "blocked",
    result: {
      blocked_reason: "verification_blocked",
      message
    }
  };
}

const draftLine = `${produced.buildName} — ${produced.genre} VR\n${produced.pagesUrl}\n\n${produced.postText}`;
const summaryMsg = produced.summary || `Threads ship draft ready for ${produced.buildName}.`;

return {
  status: "completed",
  summary: summaryMsg,
  handback: {
    message: `${summaryMsg}

Draft:
${produced.postText}

Live: ${produced.pagesUrl}
Screenshot: ${produced.screenshotPath}

Threads account OK: ${produced.threadsAccountOk ? "yes" : "no — connect via Account Center before posting"}
Source: ${produced.sourceEvidence}

Approve to post, Edit to revise, or Skip.`,
    post_draft: {
      buildName: produced.buildName,
      genre: produced.genre,
      pagesUrl: produced.pagesUrl,
      postText: produced.postText,
      screenshotPath: produced.screenshotPath,
      threadsAccountOk: produced.threadsAccountOk
    }
  }
};
